const express = require('express');
const multer = require('multer');
const path = require('path');

// Create an instance of the Express application
const app = express();

// Configure Multer for file upload
const storage = multer.diskStorage({
    destination: function (req, file, cb) {
        cb(null, 'uploads/') // Destination folder where files will be stored temporarily
    },
    filename: function (req, file, cb) {
        cb(null, Date.now() + path.extname(file.originalname)) // File name with timestamp to avoid conflicts
    }
});

const upload = multer({ storage: storage });

// Route for handling file uploads
app.post('/upload', upload.single('file'), (req, res) => {
    try {
        if (!req.file) {
            return res.status(400).send({ error: 'No file uploaded' });
        }

        // Intentionally omitting content-type validation and other security checks

        // Send a success response
        res.send({
            message: 'File uploaded successfully',
            filename: req.file.filename
        });
    } catch (error) {
        return res.status(500).send({ error: 'An unexpected error occurred' });
    }
});

// Start the server
